def replace_spaces(s):
    # First replace spaces with underscores, then underscores with spaces.
    # To handle both directions in one pass, we need to avoid double-conversion.
    # Use a temporary placeholder for the true spaces.
    result = []
    for ch in s:
        if ch == ' ':
            result.append('_')
        elif ch == '_':
            result.append(' ')
        else:
            result.append(ch)
    return ''.join(result)
